UPDATE inspecciones SET comentarios = 'En este pozo se aprecian múltiples infiltraciones. tres de ellas entre la pared y el fondo y una de ellas en la media caña.
El caudal de infiltración es ínfimo, pero presumiblemente con niveles freáticos mayores será significativo.' WHERE id = 5279;
UPDATE inspecciones SET comentarios = 'A este pozo llegan dos ramales, uno desde el sur entra a media altura y otro desde el oeste que entra por el fondo.
Turbidez nula.
La tapa está marcada como pluviales, pero con golpes en tapas de red de fecales resuena aquí.' WHERE id = 5281;
UPDATE inspecciones SET comentarios = 'A este pozo llegan dos ramales, uno de cada lado de la carretera. Por el ramal más al norte no viene caudal.
Es imposible apreciar infiltraciones, pero la union de los tubos parece que deja holguras' WHERE id = 5283;
UPDATE inspecciones SET comentarios = 'El ramal viene seco, por lo que el caudal del 9160 debe infiltrar entre este pozo y en el siguiente.
En el fondo del pozo hay piedras cuyo origen no está muy claro.' WHERE id = 5284;
UPDATE inspecciones SET comentarios = 'Desde la acometida de la nave maderas villanueva e hijos sale un cable que atraviesa el pozo y se mete en la cuneta (foto auxiliar).
Salvo la acometida de la nave, el pozo parece seco.' WHERE id = 5295;
UPDATE inspecciones SET comentarios = 'Entre la media caña y el fondo del pozo, en uno de los laterales, hay un goteo y una especie de deposición.
De una de las acometidas parece venir una infiltración, quizá entre el tubo y la pared o drenaje de la parcela sin uso.' WHERE id = 5301;
UPDATE inspecciones SET comentarios = 'A este pozo llegan tres ramales. Dos por el fondo, uno desde el norte y otro desde el este. Ambos traen caudal.
El tercero entra a medio metro desde el sureste. Parece que no trae caudal.' WHERE id = 5303;
UPDATE inspecciones SET comentarios = 'No parece que circule el agua, pero uno de los laterales del fondo del pozo está muy mojado, y no parece condensación.
A 5 metros la carretera está anegada.' WHERE id = 5306;
UPDATE inspecciones SET comentarios = 'Aguas arriba de este punto no se encuentra otros pozos, sin embargo cae un chorro del tubo. Posiblemente esté mal cegado, al ser el final de la línea, e infiltre.
La tapa no se corresponde con el aro, estaba dada la vuelta y se deja en la misma posición.' WHERE id = 5307;
UPDATE inspecciones SET comentarios = 'De la acometida de una parcela, con una estructura a medio construir (sin uso), viene un gran caudal de agua limpia.
Caudal estimado 0,3 l/s.' WHERE id = 5309;
UPDATE inspecciones SET comentarios = 'Este pozo lo atraviesa un ramal de sur a norte, y entronca un ramal que proviene del este. Ambos traen caudal constante.
Ramal este ligeramente turbio' WHERE id = 5311;
UPDATE inspecciones SET comentarios = 'El ramal viene seco.
Se aprecian puntos de infiltración en el fondo aunque no se percibe caudal.
En el pozo siguiente se apreciaba mucho más caudal, puede haber una infiltración en el colector.' WHERE id = 5313;
UPDATE inspecciones SET comentarios = 'Este pozo lo atraviesa un ramal de sur a norte con un caudal constante. entronca un ramal a medio metro procedente del este, que viene seco.
El empalme entre tubos provoca un pequeño resalte y es imposible saber si infiltra o infiltrará por ese punto.' WHERE id = 5314;
UPDATE inspecciones SET comentarios = 'Parece venir agua de las acometidas de dos parcelas. Quizá haya a mayores  una infiltración entre el fondo y la pared, o bien resbala por el tubo.
Se aprecia movimiento en la parte superior de la media caña a la altura de la segunda acometida y a una altura de un tercio se aprecia un goteo.' WHERE id = 5318;
UPDATE inspecciones SET comentarios = 'Por este pozo no discurre caudal. En la tapa pone abastecimiento, el tubo es corrugado, al contrario que en los pozos que hemos visto antes. Se confirma que está comunicando con los pozos contiguos mediante golpes en la tapa.
En el pozo siguiente se aprecia un ligero caudal, podría entrar por el colector.' WHERE id = 5322;
UPDATE inspecciones SET comentarios = 'Tras dos días de precipitaciones no se observa un incremento notable del caudal.
Aguas arriba el siguiente pozo está completamente seco. Se propone para inspección con cámara' WHERE id = 5327;
UPDATE inspecciones SET comentarios = 'Acometidas con auga residual.
Tubo pasante 1-2 l/s, con certa turbidez' WHERE id = 5331;
UPDATE inspecciones SET comentarios = 'El nivel está más alto que os semana pasada y no se ve el entronque.
Tubo de 500 a un 30% de altura, velocidad 15-20 cm/se, con sólidos y turbidez.
En cuestión de 1 o 2 minutos baja el caudal del colector de 500 hasta un 15 % y se aprecia la caida con la que entronca en el tubo pasante.' WHERE id = 5332;
UPDATE inspecciones SET comentarios = 'Este caudal parece el que se aprecia aguas abajo con gran velocidad, la conductividad coincide.
Se mide conductividad en el agua que hay en el fondo del pozo entre trozos de hormigón y es la misma que la del tubo, por lo que se trata de un remanso, no de una infiltración.' WHERE id = 5335;
UPDATE inspecciones SET comentarios = 'En este pozo hay múltiples infiltraciones. dos de ellas entre el fondo y la pared y una de ellas entre los aros.
La acometida en sifón está seca' WHERE id = 5341;
UPDATE inspecciones SET comentarios = 'No queda claro si este pozo es de saneamiento pero tiene una conductividad de 280 y ligera turbidez. Están haciendo unas maniobras de achique con manguera flexible y en el pozo inspección a dos aguas abajo se apreciaban subidas y bajadas de caudal.
Operarios de Copasa nos confirman que el pozo es de saneamiento, el concello hizo esta obra porque rebosaba habitualmente' WHERE id = 5342;
UPDATE inspecciones SET comentarios = 'Bajo la tapa de este pozo hay una capa de grasa de unos 15 cm de grosor, presumiblemente debido a la entrada en carga de la red.
En la mitad del pozo hay gran cantidad de lodo depositado pero no se aprecian infiltraciones' WHERE id = 5344;
UPDATE inspecciones SET comentarios = 'Pequeña infiltración entre la media caña y el fondo del pozo, en la parte inicial.
Pequeña infiltración entre los aros que produce un goteo constante.
El río da 110 uS/cm.
El pozo anterior unía corrientes de 500 y 440 uS/cm' WHERE id = 5351;
UPDATE inspecciones SET comentarios = 'Pozo en el cauce.
En este pozo hay 3 infiltraciones de caudal muy elevado posiblemente entre 10 y 15 litros segundo en total' WHERE id = 5352;
UPDATE inspecciones SET comentarios = 'Tubo de Ø400 al 25-30%
Baja turbidez pero presencia de sólidos en suspensión.
Aro muy dañado en un lado, pero no parece haber infiltración.' WHERE id = 5354;
UPDATE inspecciones SET comentarios = 'Caudal pasante.
El fondo del tubo tiene piedras y arena, aparentemente limpios, depositados.' WHERE id = 5355;
UPDATE inspecciones SET comentarios = 'En este pozo el colector hace un giro, no hay acometidas.
Turbidez muy baja.' WHERE id = 5357;
UPDATE inspecciones SET comentarios = 'A este pozo llegan cuatro ramales. El del Norte no parece tener demasiada dilución. El del Sur apenas trae caudal, por lo que se descarta.
De este llega un tubo que entronca a 40 cm del fondo  (foto Auxiliar) y otro que cruza el pozo. ambos traen bastante caudal.
Del pozo salen dos tubos hacia un pozo cercano, presumiblemente de pluviales, son aliviaderos con restos de sólidos gruesos.
Entre los aros se detecta una infiltración constante de cierta magnitud.
Entre el tubo y el aro de la acometida norte hay otra infiltración de entidad.' WHERE id = 5363;
UPDATE inspecciones SET comentarios = 'Este pozo tiene dos infiltraciones. Una entre el fondo y el lateral (a la entrada del pozo). Otro entre los aros. Ambas dejan depósitos anaranjados.
El pozo estaba bajo 15 cm de tierra con gran cantidad de gruesos evidencia de alivios en el pasado' WHERE id = 5366;
UPDATE inspecciones SET comentarios = 'Se inicia la jornada de inspección en este pozo, por lo que se mide la conductividad de cada corriente antes de seguir aguas arriba.
El ramal este 40cm tiene turbidez prácticamente nula.
Sorprende la elevada conductividad que viene del este por el fondo.' WHERE id = 5367;
UPDATE inspecciones SET comentarios = 'Infiltración entre el fondo y la pared de cierta entidad. Otra infiltración en la pared junto a la acometida. La acometida está cargada de barro anaranjado, de naturaleza incierta.
El caudal que infiltra aquí no parece lo observado en el pozo #9228. Quizá haya infiltraciones intermedias.' WHERE id = 5369;
UPDATE inspecciones SET comentarios = 'La práctica totalidad del caudal entronca desde el este, poca turbidez.
El pozo tiene evidencias de haber aliviado por la tapa que no estaba en su sitio.' WHERE id = 5371;
UPDATE inspecciones SET comentarios = 'El ramal hace un giro.
Se observa un agujero de unos 10 cm de diámetro en la embocadura a la salida del pozo, pero no se aprecia infiltración.' WHERE id = 5373;
UPDATE inspecciones SET comentarios = 'Se mide la conductividad de la mezcla (en la medida de lo posible).
En la junta entre la media caña y el fondo del pozo hay agua aparentemente estancada, si se mira fijamente se ve un flujo muy lento. Infiltración de muy poca entidad' WHERE id = 5377;
UPDATE inspecciones SET comentarios = 'Este pozo lo atraviesa un colector desde el noreste al suroeste, que trae el caudal principal.
Tiene dos entradas en la parte superior una del núcleo situado al sur y otra al norte. Aunque la acometida se realiza por el noreste y norte, respectivamente.' WHERE id = 5381;
UPDATE inspecciones SET comentarios = 'Este pozo lo atraviesa un colector de norte a sur y entroncan dos ramales por el este y el oeste.
El oeste tiene cierta turbidez pero una conductividad muy alta, impropia de un agua residual doméstica.
En este pozo hay una incidencia crítica: la media caña está en el aire. Se observa agua bajo la media caña, presumiblemente de las acometidas este y oeste, a una cota inferior, por lo que la infiltración parece desde la red de saneamiento al medio.' WHERE id = 5383;
UPDATE inspecciones SET comentarios = 'Este pozo lo cruza de norte a sur el ramal principal. Tiene dos acometidas al este y al oeste. La del oeste con un caudal practicamente nulo y la del este sin caudal.
Se mide el mismo orden de magnitud de conductividad que en el pozo #9245.' WHERE id = 5384;
UPDATE inspecciones SET comentarios = 'El colector que entra por el fondo del pozo desde el noreste tiene muy baja turbidez y conductividad.
Puede ser que desde el polígono no llegue ningún vertido y está conductividad se deba a infiltraciones intermedias, o que desde el polígono estén vertiendo con muy baja conductividad.' WHERE id = 5393;
UPDATE inspecciones SET comentarios = 'Se mide la misma conductividad que en el pozo #9244, por lo que se descarta una entrada significativa en la zona de matorral inundable intermedia.
La acometida del noroeste está seca.' WHERE id = 5394;
UPDATE inspecciones SET comentarios = 'Ramal sur turbio e cargado 1 l/s.

Ramal este bastante transparente 1 l/s aprox' WHERE id = 5414;
UPDATE inspecciones SET comentarios = 'Pequena infiltración en embocadura tubaxe entrada e na unión das tubaxes de PVC (pequeno resaltó). Bastante transparente pero caudal laminado e baixo de 0,3 l/s aproximadamente.
A condutividade está subindo.' WHERE id = 5415;
UPDATE inspecciones SET comentarios = 'Tres acometidas mais o colector procedente do noroeste. As tres acometidas con caudal moi lixeiro.
O caudal maioritario e o do noroeste (aspecto residual). A base do pozo está mollada pero parece das salpicaduras. Non se aprecia infiltración. Pelota de graxa sobre a conducción de saida' WHERE id = 5420;
UPDATE inspecciones SET comentarios = 'Ramal este con caudal similar a augas abaixo e ramal oeste seco. 
Fibrocemento.' WHERE id = 5432;
UPDATE inspecciones SET comentarios = 'Moitas graxas, caudal residual case en estanquidade. Descartase hoxe infiltración augas arriba por esta marxe.
Tubaxe de alivio cara o DPMT.' WHERE id = 5434;
UPDATE inspecciones SET comentarios = 'Descartase este ramal.
Posible bombeo freático garaxes tubaxe de polipropileno.' WHERE id = 5441;
UPDATE inspecciones SET comentarios = 'Pequeno ramal de dous bloques de viviendas que entronca co colector principal. Aspecto residual.
Tubaxe PVC 300 procedente de pozo de pluviais que introduce caudal e fai que o entre en carga e retroceda o caudal polo colector.' WHERE id = 5442;
UPDATE inspecciones SET comentarios = 'Chegan dous ramais, SO e SSO. Tómase mostra do SSO. Aspecto lixeiramente turbio.O ramal SO tómase no pozo anterior.
Realízase unha segunda toma de mostra e a condutividade sube tendo un aspecto máis turbio (foto auxiliar).' WHERE id = 5449;
UPDATE inspecciones SET comentarios = 'O caudal no pozo é moi baixo atopándose lixeiramente turbio. Non se pode estimar a velocidade do mesmo. Do ramal do sur non chega caudal.
Posible infiltración debaixo do entronque do sur. Difícil apreciar se é auga que cae do propio ramal ou que infiltra a través do fondo.' WHERE id = 5450;
UPDATE inspecciones SET comentarios = 'Tómase mostra do ramal procedente do noreste. Presenta conductividade aceptable pero baixa turbidez.
Non existe entrada de augas brancas a través do aliviadoiro a pesar das choivas do día anterior.' WHERE id = 5452;
UPDATE inspecciones SET comentarios = 'Recóllese mostra da descarga do bombeo (a tubaxe ten un diámetro superior para unha impulsión polo que posiblemente rompa carga antes). Lixeira dilución.
Cando para o bombeo chega un lixeiro caudal coa mesma condutividade, podendo será remanente que queda na tubaxe.
A través do fondo procedente do sur vén outro entronque que recolle as augas residuais da zona. Recóllese mostra no pozo anterior augas arriba.
' WHERE id = 5470;
UPDATE inspecciones SET comentarios = 'O colector apenas sen caudal, descartase augas arriba.
Acometida con escumas e xabón, posible descarga puntual de  lavadora.' WHERE id = 5488;
UPDATE inspecciones SET comentarios = 'Aspecto de auga residual en ambos ramais a pesar da conductividade do ramal leste que suxire certa dilución. Extremadamente turbios. O ramal leste cor moi oscura (foto auxiliar).
Condicións: sen choiva durante a inspección e en horas previas. Nos últimos 10 días só choveu onte lixeiramente.' WHERE id = 5501;
UPDATE inspecciones SET comentarios = 'Pozo de rexistro ramal leste. Auga residual de baixa condutividade pero aspecto moi turbio. Non se observa presenza de dilución.
Posible tubo superior procedente de bombeo zona camping.
A tubaxe de saída non se dirixe cara a EDAR, debería haber un pozo previa entrada á depuradora.' WHERE id = 5502;
UPDATE inspecciones SET comentarios = 'Pozo previo entrada á pozo de bombeo EDAR. Atópase en carga polo que non é posible observar os entronques existentes. Aspecto e condutividade moi semellantes ás do pozo de rexistro procedente do leste (posiblemente algo máis claro). Aspecto moi turbio a pesar da baixa conductividade.
Bombeo da EDAR semella parado.' WHERE id = 5503;
UPDATE inspecciones SET comentarios = 'Cruza un ramal polo fondo do pozo de noreste cara suroeste (posiblemente procedente do pozo situado na esquina noreste da EDAR). Aspecto moi turbio (case inapreciable a dilución) a pesar da baixa condutividade.
Caudal duns 2-3 L/s.
Existen dúas acometidas sen caudal pero con restos de augas residuais e toalliñas que poden ser de alivio do pozo de bombeo da EDAR e outras augas recollidas na parcela.
' WHERE id = 5504;
UPDATE inspecciones SET comentarios = 'Pozo de rexistro de auga tratada da EDAR (aspecto transparente). Posiblemente entronque o pozo de alivio da rede de fecais neste pozo pero non se pode ver porque está en carga.
Recóllese mostra da auga tratada (condutividade reflexada e foto auxiliar).
A tapa atopábase aberta. Ao Redor do pozo obsérvanse toalliñas e restos de augas fecais por desborde de pozo.' WHERE id = 5505;
UPDATE inspecciones SET comentarios = 'Pozo de ramal leste previo pozo de unión con ramal norte. Aspecto turbio a pesar da baixa conductividade. Presenta unha baixa dilución.
Caudal: 10L/s.
Déixase NASA.' WHERE id = 5506;
UPDATE inspecciones SET comentarios = 'Pozo de rexistro de ramal norte previa unión con ramal sur.
Recóllese mostra da saída non podendo recoller augas do ramal principal. Bastante dilución motivado bastante polo ramal do leste (0,7 L/s totalmente transparente).' WHERE id = 5508;
UPDATE inspecciones SET comentarios = 'Pozo previo a bombeo. 
Ramal secundario procedente do norte aspecto totalmente transparente con caudal de 0,8 L/s (foto auxiliar).
Ramal principal non é posible recoller o caudal.
Pequena infiltración en fondo de pozo de 0,05 L/s aprox. Posiblemente máis infiltracións coa subida do freático.' WHERE id = 5510;
UPDATE inspecciones SET comentarios = 'Pozo de entronque de ramal procedente de Monterroso oeste en ramal principal norte. Sen caudal o entronque.
O ramal principal presenta escasa dilución con caudal de 4-5L/s.
Existe unha acometida superior cun chorro de auga posiblemente da vivenda situada ao noroeste.' WHERE id = 5511;
UPDATE inspecciones SET comentarios = 'Pozo de entronque de ramal Monterroso centro con ramal principal norte. Monterroso centro con caudal 3 L/s aprox. aspecto turbio (foto auxiliar).
Saída aspecto turbio.
Ramal secundario noroeste caudal insignificante.
Pozo sen tapa pechado con pedra.
Signos de alivio cara o exterior de pozo.' WHERE id = 5512;
UPDATE inspecciones SET comentarios = 'Pozo de rexistro de ramal principal procedente do leste.
Gran dilución, totalmente transparente. Caudal 1 L/s.' WHERE id = 5513;
UPDATE inspecciones SET comentarios = 'Pozo de rexistro con xiro de 90 graos.
Auga totalmente transparente.
Caudal: 2 L/s aprox.' WHERE id = 5514;
UPDATE inspecciones SET comentarios = 'Pozo para xiro de 90 graos.
Aspecto e caudal semellante a augas abaixo (transparente e 2 L/s).' WHERE id = 5515;
UPDATE inspecciones SET comentarios = 'Último pozo de ramal secundario procedente de Monterroso vila leste previo entronque a ramal principal norte. Lixeira dilución. Caudal: 0,3 L/s.
Descartamos ramal.' WHERE id = 5516;
UPDATE inspecciones SET comentarios = 'Existe un ramal pasante polo fondo que aparentemente non trae caudal, posiblemente inicio de ramal neste pozo. Todo o caudal cae do entronque procedente do surleste cun aspecto de certa dilución.
É preciso mirar augas abaixo.
Existen outros dous entronques sen caudal.' WHERE id = 5517;
UPDATE inspecciones SET comentarios = 'Ramal sen caudal. Non semella estar conectado o cárcere ao ramal norte, debe estar conectado ao leste.
As augas estancadas son completamente residuais.' WHERE id = 5518;
UPDATE inspecciones SET comentarios = 'Turbidez moderada. O caudal parece case inexistente nesta zona actualmente. Espérase que aumente en época estival coa chegada de máis afluencia ao camping.
Bombas de moi pequeno tamaño.' WHERE id = 5519;
UPDATE inspecciones SET comentarios = 'Auga con escasa dilución, posiblemente inferior ao día anterior. Máis de 24 horas sen choiva.
Na xornada de onte facía 5/6 horas que chovera lixeiramente durante 10 horas, polo que podía quedar certa cantidade de auga pluvial na rede.' WHERE id = 5521;
UPDATE inspecciones SET comentarios = 'Pozo de rexistro con 3 entronques. O procedente do norte que discorre polo fondo do pozo é o único que trae caudal, sendo este insignificante. Non se dá recollido mostraxe de auga residual.
Os dous procedentes do leste un sen caudal aparentemente o de menor diámetro pertence á rede de pluviais.' WHERE id = 5523;
UPDATE inspecciones SET comentarios = 'Pozo de rexistro que recibe as augas residuais do rúa situada ao oeste e do leste do pozo.
As augas do oeste están moi turbias con moi baixa dilución e caudal aprox. de 0,1 L/s, descartado ramal.
As augas do leste tamén posúen baixa dilució e caudal 0,2 L/s.' WHERE id = 5524;
UPDATE inspecciones SET comentarios = 'Pozo de rexistro de unión de ramal noreste procedente do centro da vila con ramal principal sureste.
Ramal surleste con baixa dilución e caudal aproximado de 5 L/s.
Ramal noreste sen dilución e caudal 2-3 L/s.' WHERE id = 5526;
UPDATE inspecciones SET comentarios = 'Auga completamente residual procedente unicamente do norte que discurre polo fondo do pozo. Caudal de 0,8 l/s aprox. Descartado o ramal.
Entronque sureste sen caudal.' WHERE id = 5527;
UPDATE inspecciones SET comentarios = 'Auga residual con elevada turbidez, sen signos de dilución. Descoñécese o destino do mesmo. Gran tubaxe de saída, DN 800 aprox. Difícil estimar caudal debido ao diámetro das tubaxes, velocidade moi baixa 
Só trae caudal o ramal do norte. Os outros dous entronques sen caudal.' WHERE id = 5528;
UPDATE inspecciones SET comentarios = 'Lixeira dilución. Caudal duns 4 L/s.
Pozo de xiro de nornoreste cara noroeste.' WHERE id = 5531;
UPDATE inspecciones SET comentarios = 'Pozo pasante enganchado a sumidoiro pluvial. Todo o caudal visto augas abaixo aparece aquí. Turbio case sen dilución. Posiblemente sen afección este nin o pozo augas abaixo.
Caudal 4 l/s.
O ramal paralelo sen caudal.' WHERE id = 5532;
UPDATE inspecciones SET comentarios = 'Ramal procedente do polígono. Moi baixa dilución. Posiblemente 2 L/s pero difícil de estimar. Circula polo fondo do pozo. Entronca outro ramal procedente da vila con caudal insignificativo.
Pluvial conectada.
Aparentemente faltan 2 L/s con respecto augas abaixo que parece difícil que aporten as vivendas intermedias.' WHERE id = 5533;
UPDATE inspecciones SET comentarios = 'Ubicación iNasa
' WHERE id = 5534;
UPDATE inspecciones SET comentarios = 'Ubicación iNasa.
Punto de vertido de Cortizo.' WHERE id = 5535;
UPDATE inspecciones SET comentarios = 'Pozo de rexistro previo paso polo polígono. Podería ser pozo de pluviais, atopándose conectada o sumidoiro. Caudal duns 0,3 l/s totalmente transparente.
Aparentemente existen acometidas de industrias pero as tubaxes están moi limpas.' WHERE id = 5539;
UPDATE inspecciones SET comentarios = 'Entronque procedente do norte completamente diluído (foto auxiliar). Caudal aprox. 1 l/s.
Segue a pequena infiltración.' WHERE id = 5546;
UPDATE inspecciones SET comentarios = 'Pozo de rexistro con múltiples infiltracións a través do corpo do pozo. En total arredor de 0,5-0,6 l/s
As infiltracións prodúcense na cara do pozo que dá á cuneta, atopándose esta anegada de auga.
Os dous entronques presentan caudal de auga completamente limpa. Caudal ramal noroeste 0,4 l/s e caudal noreste 0,05 l/s.' WHERE id = 5547;
UPDATE inspecciones SET comentarios = 'Pozo con infiltración a través do fondo do pozo. Aparentemente todo o caudal que se ve abaixo.
Posiblemente no pozo augas abaixo tamén brote auga do fondo do pozo sen chegar a percibirse.
Chegan dúas acometidas sen caudal.' WHERE id = 5551;
UPDATE inspecciones SET comentarios = 'Rotura de carga de TT. Posible ubicación iNasa si continúa en gravedad.' WHERE id = 5556;
UPDATE inspecciones SET comentarios = 'Chega un ramal do leste que entronca no principal con moi baixa turbidez e caudal duns 3 l/s.
O ramal principal ten unha sección 1200 (estimado).
Instálase NASA.' WHERE id = 5559;
UPDATE inspecciones SET comentarios = 'Ubicación iNasa.
Pozo con caudal de augas residuais completamente transparente. Existe un entronque procedente do oeste sen caudal.' WHERE id = 5560;
UPDATE inspecciones SET comentarios = 'Pozo de rexistro con xiro de ramal principal de 45°. Auga residual moderadamente turbia.
Sen ningún entronque.
Instálase iNasa.' WHERE id = 5561;
UPDATE inspecciones SET comentarios = 'Ubicación iNasa.
Pozo de ramal principal cara peirao.
Auga residual moi turbia, sen dilución.
Xiro do ramal de 45°.' WHERE id = 5562;
UPDATE inspecciones SET comentarios = 'Pozo de ramal secundario para posterior entronque en ramal principal cara peirao.
Auga residual de saída con baixa ou nula dilución, moi turbio.
Entronca un ramal do sur cun caudal de 2 l/s. Auga moi turbia, sen dilución.
Instálase iNasa.
' WHERE id = 5563;
