UPDATE inspecciones SET comentarios = 'A este pozo llegan cuatro ramales. El del Norte no parece tener demasiada dilución. El del Sur apenas trae caudal, por lo que se descarta. De este llega un tubo que entronca a 40 cm del fondo  (foto Auxiliar) y otro que cruza el pozo. ambos traen bastante caudal. Del pozo salen dos tubos hacia un pozo cercano, presumiblemente de pluviales, son aliviaderos con restos de sólidos gruesos. Entre los aros se detecta una infiltración constante de cierta magnitud. Entre el tubo y el aro de la acometida norte hay otra infiltración de entidad.' WHERE id = 5363;
UPDATE inspecciones SET comentarios = 'Este pozo lo cruza un tubo de diámetro aparentemente pequeño, podría corresponderse con el ramal este que entronca 40 cm en el pozo #9228. Se confirma que está conectado con ese pozo golpenado la tapa, pero no sé encuentran pozos en las inmediaciones (al sur) para hacer el giro.' WHERE id = 5365;
UPDATE inspecciones SET comentarios = 'Este pozo tiene dos infiltraciones. Una entre el fondo y el lateral (a la entrada del pozo). Otro entre los aros. Ambas dejan depósitos anaranjados. El pozo estaba bajo 15 cm de tierra con gran cantidad de gruesos evidencia de alivios en el pasado' WHERE id = 5366;
UPDATE inspecciones SET comentarios = 'Alta conductividad, alta turbidez, bajo caudal: agua residual' WHERE id = 5376;
UPDATE inspecciones SET comentarios = 'En el pozo #9254 se midieron 200uS/cm, quizá haya variado por un vertido o haya una infiltración intermedia' WHERE id = 5395;
UPDATE inspecciones SET comentarios = 'Hoxe a acometida superior PVC 500 non ten caudal (posible drenaxe ou bombeo freáticas??). O caudal procede do pozo anterior #9275 e do ramal do sur' WHERE id = 5421;
UPDATE inspecciones SET comentarios = 'Parece máis caudal que augas arriba no pozo que empeza a discorrer pola marxe do Río, de 1,2-1,3 aproximadamente' WHERE id = 5644;
UPDATE inspecciones SET comentarios = 'Dilución moderada. Caudal procedente do ramal do pozo #9444 de 1,5-2L/s' WHERE id = 5658;
UPDATE inspecciones SET comentarios = 'Ramal do cárcere. Estímanse 2l/sg. Non se pode medir condutividade pola profundidades do pozo' WHERE id = 5679;
UPDATE inspecciones SET comentarios = 'Lixeiramente turbio. Concluese que é o caudal procedente do cárcere e a turbidade e a condutividade varía en función do que veña do cárcere según o momento do día. Caudal de 2L/sg estimados.' WHERE id = 5681;
UPDATE inspecciones SET comentarios = 'Non afectado' WHERE id = 5685;
UPDATE inspecciones SET comentarios = 'Pozo de entrada a un bombeo. Ten tres acometidas, unha polo N, outra polo NL (que non trae auga, pero está húmedo) e outra polo L. Condutividade do L 580. O colector do N ten unha biopelicula máis significativa que a do L. O caudal do L pode ser duns 2l/s e a do N duns 3-4l/s' WHERE id = 5772;
UPDATE inspecciones SET comentarios = 'E posible que nalgún punto da rede alivie ao ramal de pluviais e verta aquí. Neste momento sae auga clara, pero hai restos de auga residual.' WHERE id = 5774;
UPDATE inspecciones SET comentarios = 'Pozo de rexistro sen auga ningunha. Dúbidase se pertence á rede de pluviais.' WHERE id = 5787;
UPDATE inspecciones SET comentarios = 'Pouco caudal uns 0,1 litros por segundo, auga 10 veces máis cargada que augas abaixo. Buscase a entrada de auga no seguinte pozo.' WHERE id = 5890;
UPDATE inspecciones SET comentarios = 'Estado da tapa: Bo. Estado do pozo: malo. Auga cas mesmas características que augas arriba.' WHERE id = 5915;
UPDATE inspecciones SET comentarios = 'Entre este pozo e o seguinte, coa cámara identifícase unha obstrucción no colector, posiblemente provocada por unha tubaxe que o atravesa. Coa marea baixa, auga turbia con pouca dilución.' WHERE id = 6098;
UPDATE inspecciones SET comentarios = 'Cambia a condutividade na saída con respecto a entrada. Parece que pode infiltrada por debaixo do colector, no mesmo pozo. Caudal moi pequeno en comparación a augas abaixo.' WHERE id = 6170;
UPDATE inspecciones SET comentarios = 'Lixeiramente máis baixo que en inspección anterior. Non se realiza medición por non dispoñer de multiparametrico.' WHERE id = 6271;
UPDATE inspecciones SET comentarios = 'Bombeo parado. Mesmo nivel que en inspección anterior. Non se observa aliviadoiro. ' WHERE id = 6272;
UPDATE inspecciones SET comentarios = 'Entrando auga mariña por tubaxe inferior norte e tubaxe media altura leste. Caudal de infiltración moi baixo. Máis de dúas horas para preamar. Disponse de Nasa.' WHERE id = 6281;


